"""CCAR-P part B1: flashcards and questions for Evaluation, Testing and Optimization (16%), Governance,
Safety and Risk Management (14%), Stakeholder Communication and Lifecycle Management (14%) and Developer
Productivity and Operational Enablement (7%).

Written against the official Anthropic exam guide for the Claude Certified Architect - Professional
(CCAR-P, version 1.0, effective July 2026) and checked against the current Claude platform docs (evaluation,
batch processing, token counting, rate limits, data retention, data residency, compliance and administration
APIs, model deprecations, release notes), the Claude Code administration docs and the Model Context Protocol
specification. Where an item rests on general delivery or governance practice rather than a Claude fact, the
wording says so. Lessons, games, case studies and the cheat sheet for these categories live in data/ccarp_b2.py.
"""


def _fc(i, cat, front, back, detail):
    return {'id': i, 'cat': cat, 'front': front, 'back': back, 'detail': detail}


def _mc(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'mc', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _ms(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'ms', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _tf(i, cat, question, answer, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'tf', 'question': question, 'answer': answer, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


